create table public.status_venda (id uuid default gen_random_uuid() not null, loja_id uuid not null, ref_local text, nome text not null, papel text default 'producao'::text not null, ordem integer default 0, ativo boolean default true, cor text, minutos integer default 0, som boolean default false, confere_pagamento boolean default false, criado_em timestamp with time zone default now(), sucursais jsonb default '[]'::jsonb not null);
create table public.subcategorias_financeiras (id uuid default uuid_generate_v4() not null, categoria_id uuid, nome text not null, ordem integer default 0, ref_local text, alterado_em timestamp with time zone);
create table public.sucursais (id uuid default uuid_generate_v4() not null, empresa_id uuid, nome text not null, apelido text, cnpj text, telefone text, endereco text, cidade text, uf text, matriz boolean default false, ativa boolean default true, ref_local text, criado_em timestamp with time zone default now(), cor text default '#00A08B'::text, loja_id uuid, rede_id text, rede_nome text, plano text, mensalidade numeric(12,2), dia_vencimento integer, cobranca_situacao text default 'ativo'::text not null, razao_social text, nome_fantasia text, responsavel text, email text, numero text, complemento text, cep text, cobrancas jsonb default '[]'::jsonb not null, excluida_em timestamp with time zone, login_responsavel text, alterado_em timestamp with time zone);
create table public.transferencias (id uuid default gen_random_uuid() not null, loja_id uuid not null, ref_local text, numero integer, origem_suc text not null, destino_suc text not null, situacao text default 'enviada'::text, itens jsonb default '[]'::jsonb, valor_total numeric default 0, observacao text, enviada_em timestamp with time zone default now(), enviada_por text, recebida_em timestamp with time zone, recebida_por text, divergencia boolean default false, data_envio date, sucursal_id text, alterado_em timestamp with time zone);
create table public.turnos (id uuid default gen_random_uuid() not null, loja_id uuid not null, ref_local text, nome text not null, hora_inicio text, hora_fim text, ativo boolean default true, ordem integer default 0, criado_em timestamp with time zone default now(), sucursais jsonb default '[]'::jsonb not null, alterado_em timestamp with time zone);
create table public.unidades_medida (id uuid default uuid_generate_v4() not null, loja_id uuid, nome text not null, sigla text, base text, fator numeric(12,4) default 1, ref_local text, sucursais jsonb default '[]'::jsonb not null, alterado_em timestamp with time zone);
create table public.usuarios_sistema (id uuid default gen_random_uuid() not null, loja_id uuid, ref_local text, nome text, login text, senha text, ativo boolean default true, tudo boolean default false, mestre boolean default false, sucursais jsonb default '[]'::jsonb, permissoes jsonb default '{}'::jsonb, criado_em timestamp with time zone default now(), excluido_em timestamp with time zone, excluido_por text, senha_caixa text, login_app text, alterado_em timestamp with time zone);
